package app.dawnbreaker.mobile;
import android.content.Context;import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.*;import org.json.JSONArray;
final class MusicCache {
 private static final ExecutorService downloads=Executors.newFixedThreadPool(2);private static final Set<String> pending=ConcurrentHashMap.newKeySet();
 static File directory(Context c){String uid=MediaStore.prefs(c).getString("account","");return uid.matches("[a-f0-9]{32}")?new File(c.getFilesDir(),"offline-music/"+uid):null;}
 static File file(Context c,String id){File dir=directory(c);return dir!=null&&id.matches("[A-Za-z0-9_-]{1,80}")?new File(dir,id+".mp3"):null;}
 static JSONArray ids(Context c){JSONArray ids=new JSONArray();File dir=directory(c);File[] files=dir==null?null:dir.listFiles(f->f.getName().endsWith(".mp3"));if(files!=null)for(File f:files)ids.put(f.getName().substring(0,f.getName().length()-4));return ids;}
 static int count(Context c){return ids(c).length();}
 static void download(Context c,String id){File target=file(c,id);if(target==null||target.isFile()||!OfflineProxy.connected(c)||!pending.add(target.getPath()))return;String base=MediaStore.prefs(c).getString("base",""),cookie=MediaStore.prefs(c).getString("cookie","");downloads.execute(()->{HttpURLConnection connection=null;File temporary=new File(target.getPath()+".partial");try{target.getParentFile().mkdirs();connection=(HttpURLConnection)new URL(base+"/api/plugins/music/audio/"+id).openConnection();connection.setConnectTimeout(10000);connection.setReadTimeout(30000);connection.setInstanceFollowRedirects(false);connection.setRequestProperty("Cookie",cookie);if(connection.getResponseCode()!=200)throw new IOException();long size=0;try(InputStream in=connection.getInputStream();OutputStream out=new FileOutputStream(temporary)){byte[] buffer=new byte[32768];int n;while((n=in.read(buffer))!=-1){size+=n;if(size>50*1024*1024)throw new IOException();out.write(buffer,0,n);}}if(size<100||!temporary.renameTo(target))throw new IOException();trim(target.getParentFile());}catch(Exception ignored){temporary.delete();}finally{if(connection!=null)connection.disconnect();pending.remove(target.getPath());}});}
 private static void trim(File folder){File[] files=folder.listFiles(f->f.getName().endsWith(".mp3"));if(files==null)return;Arrays.sort(files,Comparator.comparingLong(File::lastModified));long size=0;for(File f:files)size+=f.length();for(File f:files){if(size<=500L*1024*1024)break;size-=f.length();f.delete();}}
 static void clear(Context c){File folder=directory(c);if(folder==null)return;File[] files=folder.listFiles();if(files!=null)for(File f:files)if(f.isFile()&&f.getName().endsWith(".mp3"))f.delete();}
}
